using UnityEngine;using LWS.TruckTaxi;
namespace LWS.TruckMattressRacing {public sealed class MattressWalker:MonoBehaviour {
 public MattressWorld world;public TruckTaxiPedestrian pedestrian;public Passersby walker;public MovePath movement;public WalkPath path;public CapsuleCollider detector;public int slot;float z;
 void Awake(){pedestrian.Expired+=Expired;pedestrian.Ragdolled+=Hit;}void Expired(TruckTaxiPedestrian p){p.PrepareForPool();transform.localScale=Vector3.zero;walker.enabled=false;detector.enabled=false;}void Hit(TruckTaxiPedestrian p){world.PedestrianHits++;foreach(var c in p.GetComponentsInChildren<Collider>(true))foreach(var r in world.match.racers)foreach(var t in r.GetComponentsInChildren<Collider>())Physics.IgnoreCollision(c,t,true);}
 public void ResetWalker(float distance){z=distance;transform.localScale=Vector3.one;float center=world.match.course.Center(z);for(int k=0;k<4;k++){var p=world.match.course.Surface(new Vector3(center+(k<2?-21:21),0,z+(k==0||k==3?-2:2)));path.pathPointTransform[k].transform.position=p;path.pathPoint[k]=p;}path.DrawCurved(false);pedestrian.Reactivate(path.getNextPoint(0,slot%4+1),Quaternion.identity,"mattress.runner."+slot,true);walker.ANIMATION_STATE=walker.LastState=PeopleAnimState.run;walker.RUN_SPEED=3.5f+slot%3*.4f;walker.enabled=false;detector.enabled=true;movement.InitStartPosition(0,slot%4+1,true,true);movement.SetLookPosition();}
 public void Step(){if(pedestrian.IsRagdoll||transform.localScale==Vector3.zero)return;walker.enabled=true;var p=transform.position;transform.position=world.match.course.Surface(p);}public void StopWalker(){walker.enabled=false;foreach(var b in GetComponentsInChildren<Rigidbody>(true))b.isKinematic=true;}
 void OnTriggerEnter(Collider other){if(!world.match.Live||world.match.Phase!=MattressPhase.Race||pedestrian.IsRagdoll)return;var r=other.GetComponentInParent<MattressRacer>();if(r==null||r.Phase!=MattressAttempt.Racing)return;var point=other.ClosestPoint(transform.position+Vector3.up*.7f);pedestrian.TryStrike(r.truck.body.GetPointVelocity(point),point);}void OnDestroy(){if(pedestrian!=null){pedestrian.Expired-=Expired;pedestrian.Ragdolled-=Hit;}}
}}
